const emptyForm = { salesAdminId: '', fullName: '', phone: '', email: '', country: 'India', state: 'Tamil Nadu', city: '', address: '', branchIds: [], status: 'ACTIVE' }
const emptyErrors = { fullName: '', phone: '', email: '', branchIds: '' }

function SalesAdminTableSkeleton() {
  const columns = ['Sales Admin ID', 'Name', 'Phone', 'Email', 'Assigned Branches', 'Status', 'Created', 'Actions']
  return <div className="sales-admin-loading-table" aria-label="Loading Sales Admin accounts"><div className="sales-admin-loading-toolbar"><span /><span /></div><div className="sales-admin-table-wrap"><table className="sales-admin-table"><thead><tr>{columns.map((column) => <th key={column}>{column}</th>)}</tr></thead><tbody>{[1, 2, 3, 4].map((row) => <tr key={row}>{columns.map((column) => <td key={column}><span /></td>)}</tr>)}</tbody></table></div></div>
}

function SalesAdminAnalyticsSkeleton() {
  return <section className="sales-admin-analytics-loading" aria-label="Loading Sales Admin analytics"><div className="sales-admin-analytics-loading-back" /><div className="sales-admin-analytics-loading-header"><span /><div><i /><b /><em /></div><span /></div><div className="sales-admin-analytics-loading-tabs"><span /><span /><span /><span /></div><div className="sales-admin-analytics-loading-kpis">{[1, 2, 3, 4, 5, 6].map((item) => <span key={item} />)}</div><div className="sales-admin-analytics-loading-columns"><div /><div /></div><div className="sales-admin-analytics-loading-card" /></section>
}

const salesAdminDateKey = (date) => { const year = date.getFullYear(); const month = String(date.getMonth() + 1).padStart(2, '0'); const day = String(date.getDate()).padStart(2, '0'); return `${year}-${month}-${day}` }
const salesAdminDateRange = (preset) => { const today = new Date(); const end = salesAdminDateKey(today); if (preset === 'thisWeek') { const start = new Date(today); const day = start.getDay() || 7; start.setDate(start.getDate() - day + 1); return { preset, startDate: salesAdminDateKey(start), endDate: end } } const start = new Date(today.getFullYear(), today.getMonth(), 1); return { preset: 'thisMonth', startDate: salesAdminDateKey(start), endDate: end } }

function SalesAdminDateRangeFilter({ value, onChange }) {
  const [preset, setPreset] = useState(value?.preset || 'thisMonth')
  const [startDate, setStartDate] = useState(value?.startDate || '')
  const [endDate, setEndDate] = useState(value?.endDate || '')
  const updatePreset = (nextPreset) => { setPreset(nextPreset); if (nextPreset !== 'custom') { const range = salesAdminDateRange(nextPreset); setStartDate(range.startDate); setEndDate(range.endDate); onChange(range) } }
  const updateCustom = (field, nextValue) => { const nextStart = field === 'startDate' ? nextValue : startDate; const nextEnd = field === 'endDate' ? nextValue : endDate; setPreset('custom'); if (field === 'startDate') setStartDate(nextValue); else setEndDate(nextValue); if (nextStart && nextEnd && nextStart <= nextEnd) onChange({ preset: 'custom', startDate: nextStart, endDate: nextEnd }) }
  return <div className="sales-admin-date-filter" aria-label="Sales Admin analytics date range"><label><span>Date range</span><select value={preset} onChange={(event) => updatePreset(event.target.value)}><option value="thisMonth">This Month</option><option value="thisWeek">This Week</option><option value="custom">Custom Range</option></select></label>{preset === 'custom' ? <><label><span>From</span><input type="date" value={startDate} onChange={(event) => updateCustom('startDate', event.target.value)} /></label><label><span>To</span><input type="date" min={startDate || undefined} value={endDate} onChange={(event) => updateCustom('endDate', event.target.value)} /></label></> : null}</div>
}

function SalesAdminReportsPanel({ admin }) {
  const [reports, setReports] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [search, setSearch] = useState('')
  const [reportPage, setReportPage] = useState(1)
  useEffect(() => { let active = true; setLoading(true); listSalesCrmReportSubmissions(admin?.id).then((response) => { if (active) setReports(response?.data || []) }).catch((reason) => { if (active) setError(reason?.message || 'Unable to load submitted reports.') }).finally(() => { if (active) setLoading(false) }); return () => { active = false } }, [admin?.id])
  const rows = reports.filter((report) => `${report.reportName} ${report.reportType} ${report.fileName}`.toLowerCase().includes(search.toLowerCase()))
  useEffect(() => { setReportPage(1) }, [search])
  useEffect(() => {
    const table = document.querySelector('.sales-admin-reports-table')
    if (!table) return undefined
    const pageSize = 5
    const pageCount = Math.max(1, Math.ceil(rows.length / pageSize))
    const currentPage = Math.min(reportPage, pageCount)
    table.querySelectorAll('tbody tr').forEach((row, index) => { row.style.display = index >= (currentPage - 1) * pageSize && index < currentPage * pageSize ? '' : 'none' })
    const container = table.closest('.sales-admin-reports-table-wrap')
    container?.querySelector('.sales-admin-reports-pagination')?.remove()
    if (!container || pageCount <= 1) return undefined
    const pagination = document.createElement('div')
    pagination.className = 'sales-admin-reports-pagination'
    const label = document.createElement('span')
    label.textContent = `Page ${currentPage} of ${pageCount} · ${rows.length} reports`
    pagination.appendChild(label)
    const controls = document.createElement('div')
    const addButton = (text, disabled, nextPage) => { const button = document.createElement('button'); button.type = 'button'; button.textContent = text; button.disabled = disabled; button.onclick = () => setReportPage(nextPage); controls.appendChild(button) }
    addButton('Previous', currentPage === 1, Math.max(1, currentPage - 1))
    for (let page = 1; page <= pageCount; page += 1) addButton(String(page), page === currentPage, page)
    addButton('Next', currentPage === pageCount, Math.min(pageCount, currentPage + 1))
    pagination.appendChild(controls)
    container.appendChild(pagination)
    return undefined
  }, [rows, reportPage])
  useEffect(() => {
    const table = document.querySelector('.sales-admin-reports-table')
    if (!table) return undefined
    const header = table.querySelector('thead tr')
    if (!header || header.querySelector('[data-submitted-by-column]')) return undefined
    const submittedHeader = document.createElement('th')
    submittedHeader.textContent = 'Submitted By'
    submittedHeader.dataset.submittedByColumn = 'true'
    header.insertBefore(submittedHeader, header.children[2])
    table.querySelectorAll('tbody tr').forEach((row) => {
      const cell = document.createElement('td')
      cell.textContent = admin?.fullName || admin?.name || 'Sales Admin'
      row.insertBefore(cell, row.children[2])
    })
    return undefined
  }, [rows, admin?.fullName, admin?.name])
  const download = async (report) => { const response = await downloadSalesCrmReportSubmission(report.id); if (!response?.blob) return; const url = URL.createObjectURL(response.blob); const link = document.createElement('a'); link.href = url; link.download = response.fileName || report.fileName; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url) }
  return <section className="sales-admin-profile-card sales-admin-reports-card"><div className="sales-admin-reports-heading"><div><span className="sales-admin-profile-kicker">SUBMITTED REPORTS</span><h2>Reports</h2></div><input type="search" placeholder="Search reports" value={search} onChange={(event) => setSearch(event.target.value)} /></div>{error ? <p className="sales-admin-profile-error">{error}</p> : loading ? <div className="sales-admin-reports-skeleton">{[1, 2, 3, 4].map((item) => <span key={item} />)}</div> : rows.length ? <div className="sales-admin-reports-table-wrap"><table className="sales-admin-reports-table"><thead><tr><th>Report ID</th><th>Report Name</th><th>Type</th><th>Period</th><th>Submitted At</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map((report) => <tr key={report.id}><td>{report.id}</td><td><strong>{report.reportName}</strong><small>{report.fileName}</small></td><td>{report.reportType}</td><td>{report.fromDate} to {report.toDate}</td><td>{new Date(report.createdAt).toLocaleString('en-IN')}</td><td><span className={`sales-admin-report-status is-${String(report.status).toLowerCase()}`}>{report.status}</span></td><td><button type="button" onClick={() => void download(report)}>Download</button></td></tr>)}</tbody></table></div> : <p className="sales-admin-profile-empty">No reports submitted by this Sales Admin.</p>}</section>
}

function SalesAdminProfileView({ admin, onClose, onEdit }) {
  const [tab, setTab] = useState('overview')
  const metrics = admin?.leadMetrics || {}
  const statusLabel = admin?.mustResetPassword ? 'Pending' : admin?.active ? 'Active' : 'Inactive'
  const value = (item) => item === null || item === undefined || item === '' ? 'Not provided' : item
  const noteValue = (item) => item === null || item === undefined || String(item).trim() === '' ? '-' : item
  const formatTime = (time) => {
    if (!time) return '-'
    const [hours, minutes] = String(time).split(':').map(Number)
    if (Number.isNaN(hours) || Number.isNaN(minutes)) return time
    const suffix = hours >= 12 ? 'PM' : 'AM'
    const displayHours = hours % 12 || 12
    return `${displayHours}:${String(minutes).padStart(2, '0')} ${suffix}`
  }
  const initials = String(admin?.fullName || 'SA').split(/\s+/).filter(Boolean).slice(0, 2).map((item) => item[0]).join('').toUpperCase()
  const fields = [['Sales Admin ID', admin?.userCode], ['Full Name', admin?.fullName], ['Phone Number', admin?.phone], ['Email Address', admin?.email], ['Country', admin?.country], ['State', admin?.state], ['City', admin?.city], ['Address', admin?.address], ['Account Status', statusLabel], ['Created Date', admin?.createdAt ? new Date(admin.createdAt).toLocaleDateString('en-IN') : null]]
  const cards = [['Total Leads', metrics.leadCount ?? 0, 'total'], ['HOT Leads', metrics.hotCount ?? 0, 'hot'], ['WARM Leads', metrics.warmCount ?? 0, 'warm'], ['COLD Leads', metrics.coldCount ?? 0, 'cold'], ['CLOSED Leads', metrics.closedCount ?? 0, 'closed'], ['Converted Leads / Admissions', metrics.admissionCount ?? 0, 'admission']]
  const personal = <section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">PROFILE INFORMATION</span><h3>Personal information</h3><div className="sales-admin-profile-detail-grid">{fields.map(([label, item]) => <div key={label}><span>{label}</span><strong>{value(item)}</strong></div>)}</div></section>
  const branches = <section className="sales-admin-profile-card"><div className="sales-admin-profile-section-heading"><div><span className="sales-admin-profile-kicker">ACCESS SCOPE</span><h3>Assigned branches</h3></div><span className="sales-admin-profile-count">{admin?.branches?.length || 0}</span></div>{admin?.branches?.length ? <div className="sales-admin-profile-branches">{admin.branches.map((branch) => <div className="sales-admin-profile-branch" key={branch.id}><strong>{value(branch.branchName)}</strong><span>{value(branch.branchId)}</span></div>)}</div> : <p className="sales-admin-profile-empty">No branches assigned.</p>}</section>
  const performance = <section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">SALES PERFORMANCE</span><h3>Lead summary</h3><div className="sales-admin-profile-metrics">{cards.map(([label, count, tone]) => <div className={`sales-admin-profile-metric is-${tone}`} key={label}><span>{label}</span><strong>{count}</strong></div>)}</div></section>
  return <div className="sales-admin-profile-view" role="dialog" aria-modal="true" aria-labelledby="sales-admin-profile-title"><header className="sales-admin-profile-header"><div className="sales-admin-profile-avatar">{initials}</div><div className="sales-admin-profile-title"><span className="sales-admin-profile-kicker">SALES ADMIN PROFILE</span><h2 id="sales-admin-profile-title">{value(admin?.fullName)}</h2><div className="sales-admin-profile-meta"><span>{value(admin?.userCode)}</span><span className={`sales-admin-profile-status is-${statusLabel.toLowerCase()}`}>{statusLabel}</span></div></div><div className="sales-admin-profile-actions"><button type="button" className="sales-admin-profile-edit" onClick={() => onEdit(admin)}>Edit Sales Admin</button><button type="button" className="sales-admin-profile-close" onClick={onClose} aria-label="Close Sales Admin details">&times;</button></div></header><nav className="sales-admin-profile-tabs" aria-label="Sales Admin detail sections">{[['overview', 'Overview'], ['branches', 'Assigned Branches'], ['statistics', 'Lead Statistics'], ['activity', 'Recent Activity']].map(([key, label]) => <button type="button" key={key} className={tab === key ? 'is-active' : ''} onClick={() => setTab(key)}>{label}</button>)}</nav><div className="sales-admin-profile-content">{tab === 'overview' ? personal : null}{tab === 'branches' ? branches : null}{tab === 'statistics' ? <>{performance}<section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">LEAD DISTRIBUTION</span><h3>Current stage distribution</h3><div className="sales-admin-profile-distribution">{cards.slice(1, 5).map(([label, count, tone]) => <div key={label}><span className={`sales-admin-profile-distribution-bar is-${tone}`} style={{ '--sales-admin-profile-value': `${metrics.leadCount ? Math.round((Number(count) / metrics.leadCount) * 100) : 0}%` }} /><div><strong>{label}</strong><span>{count} leads</span></div></div>)}</div></section></> : null}{tab === 'reports' ? <SalesAdminReportsPanel admin={admin} /> : null}{tab === 'activity' ? <section className="sales-admin-profile-card sales-admin-profile-empty-state"><span className="sales-admin-profile-kicker">RECENT ACTIVITY</span><h3>Activity timeline unavailable</h3><p>The current profile endpoint does not provide activity history.</p></section> : null}</div></div>
}

function SalesAdminAnalyticsViewBase({ admin, onBack, onEdit, dateRange, onDateRangeChange, initialTab = 'overview' }) {
  const [tab, setTab] = useState(initialTab === 'reports' ? 'overview' : initialTab)
  useEffect(() => {
    const tabs = document.querySelector('.sales-admin-analytics-page .sales-admin-profile-tabs')
    if (!tabs || tabs.querySelector('[data-sales-admin-reports-tab]')) return undefined
    const activeRouteTab = new URLSearchParams(window.location.search).get('tab')
    const reportsButton = document.createElement('button')
    reportsButton.type = 'button'
    reportsButton.textContent = 'Reports'
    reportsButton.dataset.salesAdminReportsTab = 'true'
    reportsButton.onclick = () => {
      const params = new URLSearchParams(window.location.search)
      params.set('tab', 'reports')
      window.history.pushState({}, '', `${window.location.pathname}?${params.toString()}`)
      tabs.querySelectorAll('button').forEach((button) => button.classList.remove('is-active'))
      reportsButton.classList.add('is-active')
      tabs.closest('.sales-admin-analytics-page')?.querySelectorAll(':scope > .sales-admin-analytics-kpis, :scope > .sales-admin-analytics-two-column, :scope > .sales-admin-profile-card').forEach((node) => { node.style.display = 'none' })
      const reportsSection = document.querySelector('.sales-admin-reports-route')
      if (reportsSection) reportsSection.style.display = 'block'
    }
    tabs.appendChild(reportsButton)
    if (activeRouteTab === 'reports') {
      tabs.querySelectorAll('button').forEach((button) => button.classList.remove('is-active'))
      reportsButton.classList.add('is-active')
    }
    const tabValues = { Overview: 'overview', 'Follow-up Analytics': 'followups', Admissions: 'admissions' }
    const routeHandlers = []
    tabs.querySelectorAll('button:not([data-sales-admin-reports-tab])').forEach((button) => {
      const nextTab = tabValues[button.textContent.trim()]
      if (!nextTab) return
      const handler = () => {
        const params = new URLSearchParams(window.location.search)
        params.set('tab', nextTab)
        window.history.pushState({}, '', `${window.location.pathname}?${params.toString()}`)
        tabs.querySelectorAll('button').forEach((item) => item.classList.toggle('is-active', item === button))
        tabs.closest('.sales-admin-analytics-page')?.querySelectorAll(':scope > .sales-admin-analytics-kpis, :scope > .sales-admin-analytics-two-column, :scope > .sales-admin-profile-card').forEach((node) => { node.style.display = 'block' })
        const reportsSection = document.querySelector('.sales-admin-reports-route')
        if (reportsSection) reportsSection.style.display = 'none'
      }
      button.addEventListener('click', handler)
      routeHandlers.push([button, handler])
    })
    return () => { routeHandlers.forEach(([button, handler]) => button.removeEventListener('click', handler)); reportsButton.remove() }
  }, [])
  const metrics = admin?.leadMetrics || {}
  const total = Number(metrics.leadCount || 0)
  const value = (item) => item === null || item === undefined || item === '' ? 'Not provided' : item
  const noteValue = (item) => item === null || item === undefined || String(item).trim() === '' ? '-' : item
  const formatTime = (time) => {
    if (!time) return '-'
    const [hours, minutes] = String(time).split(':').map(Number)
    if (Number.isNaN(hours) || Number.isNaN(minutes)) return time
    const suffix = hours >= 12 ? 'PM' : 'AM'
    const displayHours = hours % 12 || 12
    return `${displayHours}:${String(minutes).padStart(2, '0')} ${suffix}`
  }
  const cards = [['Total Leads', metrics.leadCount ?? 0, 'total'], ['HOT Leads', metrics.hotCount ?? 0, 'hot'], ['WARM Leads', metrics.warmCount ?? 0, 'warm'], ['COLD Leads', metrics.coldCount ?? 0, 'cold'], ['CLOSED Leads', metrics.closedCount ?? 0, 'closed'], ['Converted Admissions', metrics.admissionCount ?? 0, 'admission'], ['Pending Follow-ups', metrics.pendingFollowUpCount ?? 0, 'warm'], ['Overdue Follow-ups', metrics.overdueFollowUpCount ?? 0, 'hot']]
  const breakdown = (items) => Object.entries(items || {}).sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, 6)
  const stageRows = [['HOT', metrics.hotCount || 0, 'hot'], ['WARM', metrics.warmCount || 0, 'warm'], ['COLD', metrics.coldCount || 0, 'cold'], ['CLOSED', metrics.closedCount || 0, 'closed']]
  const personal = initialTab === 'reports' ? [['Submitted Reports', <SalesAdminReportsPanel admin={admin} />]] : [['Sales Admin ID', admin?.userCode], ['Email Address', admin?.email], ['Phone Number', admin?.phone], ['Country', admin?.country], ['State', admin?.state], ['City', admin?.city], ['Account Status', admin?.active ? 'Active' : 'Inactive'], ['Created Date', admin?.createdAt ? new Date(admin.createdAt).toLocaleDateString('en-IN') : null]]
  return <section className="sales-admin-analytics-page"><header className="sales-admin-analytics-header"><button type="button" className="sales-admin-analytics-back" onClick={onBack}>← Back to Sales Admins</button><div className="sales-admin-analytics-identity"><div className="sales-admin-analytics-avatar">{String(admin?.fullName || 'SA').split(/\s+/).filter(Boolean).slice(0, 2).map((item) => item[0]).join('').toUpperCase()}</div><div><span className="sales-admin-profile-kicker">SALES ADMIN ANALYTICS</span><h1>{value(admin?.fullName)}</h1><p>{value(admin?.userCode)} · {value(admin?.email)}</p></div><span className={`sales-admin-profile-status is-${admin?.active ? 'active' : 'inactive'}`}>{admin?.active ? 'Active' : 'Inactive'}</span></div><div className="sales-admin-analytics-actions"><button type="button" className="sales-admin-profile-edit" onClick={() => onEdit(admin)}>Edit Sales Admin</button><SalesAdminDateRangeFilter value={dateRange} onChange={onDateRangeChange} /></div></header><nav className="sales-admin-profile-tabs" aria-label="Sales Admin analytics sections">{[['overview', 'Overview'], ['followups', 'Follow-up Analytics'], ['admissions', 'Admissions'], ].map(([key, label]) => <button type="button" key={key} className={tab === key ? 'is-active' : ''} onClick={() => setTab(key)}>{label}</button>)}</nav>{tab === 'overview' ? <><section className="sales-admin-analytics-kpis">{cards.map(([label, count, tone]) => <div className={`sales-admin-profile-metric is-${tone}`} key={label}><span>{label}</span><strong>{count}</strong></div>)}</section><div className="sales-admin-analytics-two-column"><section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">LEAD STAGE ANALYSIS</span><h2>Current lead distribution</h2>{stageRows.map(([label, count, tone]) => <div className="sales-admin-analytics-stage-row" key={label}><div><strong>{label} Leads</strong><span>{count} leads · {total ? Math.round((Number(count) / total) * 100) : 0}%</span></div><div className={`sales-admin-analytics-stage-bar is-${tone}`}><i style={{ width: `${total ? Math.round((Number(count) / total) * 100) : 0}%` }} /></div></div>)}</section><section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">ASSIGNED BRANCHES</span><h2>Branch scope</h2>{admin?.branches?.length ? <div className="sales-admin-profile-branches">{admin.branches.map((branch) => <div className="sales-admin-profile-branch" key={branch.id}><strong>{value(branch.branchName)}</strong><span>{value(branch.branchId)}</span></div>)}</div> : <p className="sales-admin-profile-empty">No branches assigned.</p>}</section></div><section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">PROFILE DETAILS</span><h2>Account information</h2><div className="sales-admin-profile-detail-grid">{personal.map(([label, item]) => <div key={label}><span>{label}</span><strong>{value(item)}</strong></div>)}</div></section></> : null}{tab === 'stages' ? <section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">STAGE BREAKDOWN</span><h2>Lead stage analysis</h2><div className="sales-admin-analytics-stage-grid">{stageRows.map(([label, count, tone]) => <div className={`sales-admin-profile-metric is-${tone}`} key={label}><span>{label} Leads</span><strong>{count}</strong><small>{total ? Math.round((Number(count) / total) * 100) : 0}% of total leads</small></div>)}</div><p className="sales-admin-profile-note">Counts reflect the current stage stored for leads created by this Sales Admin.</p></section> : null}{tab === 'followups' ? <section className="sales-admin-profile-card sales-admin-followups-card"><span className="sales-admin-profile-kicker">FOLLOW-UP ANALYTICS</span><h2>Student follow-up records</h2><div className="sales-admin-analytics-kpis sales-admin-followup-kpis"><div className="sales-admin-profile-metric is-warm"><span>Pending</span><strong>{metrics.pendingFollowUpCount ?? 0}</strong></div><div className="sales-admin-profile-metric is-hot"><span>Overdue</span><strong>{metrics.overdueFollowUpCount ?? 0}</strong></div><div className="sales-admin-profile-metric is-total"><span>Total Records</span><strong>{metrics.followUpRecords?.length ?? 0}</strong></div></div>{metrics.followUpRecords?.length ? <div className="sales-admin-followups-table-wrap"><table className="sales-admin-followups-table"><thead><tr><th>Student / Lead</th><th>Contact</th><th>Stage</th><th>Course / Branch</th><th>Last Follow-up</th><th>Next Follow-up</th><th>Status</th><th>Notes</th></tr></thead><tbody>{metrics.followUpRecords.map((item) => <tr key={item.leadId}><td><strong>{value(item.studentName)}</strong><small>{value(item.leadId)}</small></td><td><span>{value(item.phoneNumber)}</span><small>{value(item.email)}</small></td><td>{value(item.stage)}</td><td><strong>{value(item.courseName)}</strong><small>{value(item.branchName)}</small></td><td>{item.lastFollowUpDate ? new Date(item.lastFollowUpDate).toLocaleDateString('en-IN') : '-'}</td><td>{item.nextFollowUpDate ? `${new Date(item.nextFollowUpDate).toLocaleDateString('en-IN')}${item.nextFollowUpTime ? ` · ${formatTime(item.nextFollowUpTime)}` : ''}` : 'Not scheduled'}</td><td><span className={`sales-admin-followup-status is-${String(item.followUpStatus || '').toLowerCase()}`}>{item.followUpStatus}</span></td><td>{noteValue(item.notes)}</td></tr>)}</tbody></table></div> : <p className="sales-admin-profile-empty">No follow-up students available.</p>}</section> : null}{tab === 'admissions' ? <section className="sales-admin-profile-card sales-admin-admissions-card"><span className="sales-admin-profile-kicker">ADMISSION CONVERSION</span><h2>Converted admissions</h2><div className="sales-admin-analytics-conversion"><strong>{metrics.admissionCount ?? 0}</strong><span>{total ? Math.round((Number(metrics.admissionCount || 0) / total) * 100) : 0}% conversion from {total} leads</span></div>{metrics.admissionRecords?.length ? <div className="sales-admin-admissions-table-wrap"><table className="sales-admin-admissions-table"><thead><tr><th>Student</th><th>Original Lead</th><th>Contact</th><th>Course / Branch</th><th>Admission Date</th><th>Batch / Faculty</th></tr></thead><tbody>{metrics.admissionRecords.map((student) => <tr key={student.studentId}><td><strong>{value(student.studentName)}</strong><small>{value(student.studentId)}</small></td><td>{value(student.leadId)}</td><td><span>{value(student.phoneNumber)}</span><small>{value(student.email)}</small></td><td><strong>{value(student.courseName)}</strong><small>{value(student.branchName)}</small></td><td>{value(student.admissionDate)}</td><td><strong>{value(student.batchName)}</strong><small>{value(student.facultyName)}</small></td></tr>)}</tbody></table></div> : <p className="sales-admin-profile-empty">No converted student admissions available.</p>}</section> : null}{tab === 'records' ? <section className="sales-admin-profile-card"><span className="sales-admin-profile-kicker">RECENT LEAD RECORDS</span><h2>Latest leads</h2>{metrics.recentLeads?.length ? <div>{metrics.recentLeads.map((lead) => <div className="sales-admin-analytics-list-row" key={lead.leadId}><div><strong>{value(lead.studentName)}</strong><small>{value(lead.leadId)} · {value(lead.courseName)}</small></div><span>{value(lead.stage)}</span></div>)}</div> : <p className="sales-admin-profile-empty">No lead records available.</p>}</section> : null}{tab === 'activity' ? <section className="sales-admin-profile-card sales-admin-profile-empty-state"><span className="sales-admin-profile-kicker">ACTIVITY HISTORY</span><h2>Recent activity</h2>{metrics.activityRecords?.length ? <div className="sales-admin-activity-list">{metrics.activityRecords.map((activity) => <div className="sales-admin-activity-row" key={activity.id}><div><strong>{value(activity.action)}</strong><span>{value(activity.studentName)} · {value(activity.leadId)}</span><small>{value(activity.branchName)} · Updated by {value(activity.updatedBy)}</small></div><time>{activity.createdAt ? new Date(activity.createdAt).toLocaleString("en-IN") : "-"}</time></div>)}</div> : <p className="sales-admin-profile-empty">No activity records available for this date range.</p>}</section> : null}</section>
}

function SalesAdminAnalyticsView(props) {
  return <div className={`sales-admin-reports-view ${props.initialTab === 'reports' ? 'is-reports' : ''}`}><SalesAdminAnalyticsViewBase {...props} initialTab={props.initialTab === 'reports' ? 'overview' : props.initialTab} /><section className="sales-admin-analytics-page sales-admin-reports-route"><SalesAdminReportsPanel admin={props.admin} /></section></div>
}

