  const load = async () => { setLoading(true); try { const params = new URLSearchParams({ includeCombinedBranchAdmins: 'true', startDate: analyticsDateRange.startDate, endDate: analyticsDateRange.endDate }); const [branchResult, adminResult] = await Promise.all([listBranches({ limit: 100 }), request(`/sales-admins?${params.toString()}`)]); setBranches((branchResult.data || []).filter((branch) => String(branch.status).toLowerCase() !== 'inactive')); const rows = adminResult?.data || []; setAdmins(rows.map((admin) => ({ ...admin, mustResetPassword: false }))) } catch (error) { setStatus({ type: 'error', message: error?.message || 'Unable to load Sales Admin data.' }) } finally { setLoading(false) } }
