  useEffect(() => { if (!selectedCountryCode || !selectedStateCode) { setCityOptions([]); return undefined } let cancelled = false; getCitiesOfState(selectedCountryCode, selectedStateCode).then((items) => { if (!cancelled) setCityOptions(Array.isArray(items) ? [...items].sort((a, b) => String(a?.name || '').localeCompare(String(b?.name || ''))) : []) }).catch(() => { if (!cancelled) setCityOptions([]) }); return () => { cancelled = true } }, [selectedCountryCode, selectedStateCode])
  useEffect(() => { const close = (event) => { const searchInput = event.target.closest('input[type="search"]'); if (searchInput) { window.setTimeout(() => setIsBranchDropdownOpen(true), 0); return } const insideBranchUi = event.target.closest('.sales-admin-branch-picker [role="listbox"]') || event.target.closest('.sales-admin-branch-picker > span'); if (!insideBranchUi) setIsBranchDropdownOpen(false); if (!event.target.closest('.sales-admin-actions')) setActiveMenuId(null) }; document.addEventListener('pointerdown', close); document.addEventListener('click', close); return () => { document.removeEventListener('pointerdown', close); document.removeEventListener('click', close) } }, [])
  useEffect(() => { const find = (button) => { const label = button?.getAttribute('aria-label') || ''; return admins.find((admin) => label.includes(admin.fullName || admin.name || admin.email)) }; const over = (event) => { const action = event.target.closest?.('.sales-admin-actions'); if (action) setActiveMenuId(find(action.querySelector('.sales-admin-menu-button'))?.id || null) }; const out = (event) => { const action = event.target.closest?.('.sales-admin-actions'); if (action && !action.contains(event.relatedTarget) && pinnedMenuId === null) setActiveMenuId(null) }; const click = (event) => { const admin = find(event.target.closest?.('.sales-admin-menu-button')); if (admin) window.setTimeout(() => { setPinnedMenuId(admin.id); setActiveMenuId(admin.id) }, 0); else if (!event.target.closest('.sales-admin-actions')) { setPinnedMenuId(null); setActiveMenuId(null) } }; document.addEventListener('mouseover', over); document.addEventListener('mouseout', out); document.addEventListener('click', click); return () => { document.removeEventListener('mouseover', over); document.removeEventListener('mouseout', out); document.removeEventListener('click', click) } }, [admins, pinnedMenuId])
